tions":["RECORD_CONTEXT","REQUEST_MEDICAL_REVIEW"],"linked_protocols":["behavioral_check"],"match_policy":"ALL","model_status":"ENGINEERING_TEST_ONLY","sensor_rules":[{"metric":"distress_score","op":"GE","threshold_value":8,"source_sensor":"SELF_REPORT","values_json":{},"likelihood_ratio":3.0,"severity_tier":"YELLOW","weight_basis":"ENGINEERING_TEST_ONLY_NOT_CLINICALLY_VALIDATED","description":"Regra sintética de integração; requer validação clínica antes de uso decisório."}],"questions":[{"prompt":"Você deseja apoio de outro tripulante ou contato com a equipe de suporte?","positive_concepts":["humor deprimido","ansiedade"],"yes_likelihood":3.0,"no_likelihood":0.5,"linked_protocol_id":"behavioral_check"}],"contraindications":[{"blocked_action":"ISOLATE_IN_DISTRESS","guard_metric":"requests_help","guard_op":"EQ","guard_value":1,"rationale":"Guarda de segurança do protótipo; revisão clínica e autorização da missão são necessárias. O limiar 500 de ferritina é um requisito de teste, não diagnóstico ou recomendação de dose."}]}]}') ON CONFLICT(report_id) DO UPDATE SET source_id=excluded.source_id,hazard_id=excluded.hazard_id,category=excluded.category,title=excluded.title,problem=excluded.problem,content_text=excluded.content_text,symptoms_text=excluded.symptoms_text,countermeasures_text=excluded.countermeasures_text,payload_json=excluded.payload_json;
