INSERT INTO clinical_reports(report_id,source_id,hazard_id,category,title,problem,content_text,symptoms_text,countermeasures_text,payload_json) VALUES ('HRP-PROJECT-ONE_CARBON_METABOLISM','NASA-ONE-CARBON','GRAVITY_FIELDS','BEHAVIORAL_BIOCHEMICAL','Via de um carbono e vitaminas B','Associações entre metabolismo de um carbono e SANS são investigativas; suplementação não é uma contramedida universal comprovada.','Referência de pesquisa/risco; não protocolo diagnóstico validado. Regras numéricas, priors e LRs são fixtures de engenharia. Entrevista contextual e registros de qualidade. LAB quando disponível; ausência permanece NULL.','marcador bioquímico alterado alteração visual','Registrar contexto e conferir a qualidade das observações. Solicitar avaliação pelo protocolo médico autorizado para a missão.','{"schema_version":1,"report_id":"HRP-PROJECT-ONE_CARBON_METABOLISM","source_id":"NASA-ONE-CARBON","hazard_id":"GRAVITY_FIELDS","category":"BEHAVIORAL_BIOCHEMICAL","title":"Via de um carbono e vitaminas B","problem":"Associações entre metabolismo de um carbono e SANS são investigativas; suplementação não é uma contramedida universal comprovada.","primary_symptoms":["marcador bioquímico alterado"],"secondary_symptoms":["alteração visual"],"detection":["Entrevista contextual e registros de qualidade.","LAB quando disponível; ausência permanece NULL."],"scientific_scope":"Referência de pesquisa/risco; não protocolo diagnóstico validado. Regras numéricas, priors e LRs são fixtures de engenharia.","conditions":[{"condition_id":"ONE_CARBON_METABOLISM","name":"Via de um carbono e vitaminas B","source_id":"NASA-ONE-CARBON","subsystem":"NEURO_OCULAR_SANS","prior":0.05,"default_escalation":"CREW","recommended_mission_mode":"MODE_REST_VITALS","symptoms":["marcador bioquímico alterado","alteração visual"],"countermeasures":["Registrar contexto e conferir a qualidade das observações.","Solicitar avaliação pelo protocolo médico autorizado para a missão."],"actions":["RECORD_CONTEXT